INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m24573$nota-0064$m24573$, $m24574$Training and Racing with a Power Meter.pdf$m24574$, $m24575$161$m24575$, $m24576$TABLE 7.4 Training Stress Score (TSS) and Intensity Factor (IF) for Different Rides — inclui exemplos como '40 km TT, male Cat. II rider — 0:53 — TSS 89 — IF 1.02' e '2018 US Elite National Championships, Cat. I — 5:22 — TSS 272 — IF 0.71'.$m24576$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m24577$nota-0064$m24577$, $m24578$nota-0062$m24578$, $m24579$complementa$m24579$, $m24580$exemplos reais de TSS calculado pela fórmula da nota-0062, para calibrar expectativa por tipo/duração de evento$m24580$)
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m24581$nota-0064$m24581$, $m24582$nota-0063$m24582$, $m24583$complementa$m24583$, $m24584$esses valores de TSS podem ser cruzados com a escala de fadiga da nota-0063$m24584$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m24585$nota-0065$m24585$, $m24586$Training and Racing with a Power Meter.pdf$m24586$, $m24587$164$m24587$, $m24588$AEPF = (P × 60) ÷ (C × 2 × π × CL) where AEPF is average effective pedal force (in newtons, or N); P is power (in watts); C is cadence (in rpm); CL is crank length (in meters).$m24588$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m24589$nota-0065$m24589$, $m24590$nota-0066$m24590$, $m24591$complementa$m24591$, $m24592$AEPF e CPV (nota-0066) juntos formam os dois eixos da Quadrant Analysis (nota-0067)$m24592$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m24593$nota-0066$m24593$, $m24594$Training and Racing with a Power Meter.pdf$m24594$, $m24595$165$m24595$, $m24596$CPV = (C × CL × 2 × π) ÷ 60 where CPV is circumferential pedal velocity (in meters/second); C is cadence (in rpm); CL is crank length (in meters).$m24596$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m24597$nota-0066$m24597$, $m24598$Training and Racing with a Power Meter.pdf$m24598$, $m24599$165$m24599$, $m24600$Because crank length is generally constant, especially for a given individual, one could just as well use cadence instead of circumferential pedal velocity. We have used the latter to be consistent with scientific convention.$m24600$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m24601$nota-0066$m24601$, $m24602$nota-0065$m24602$, $m24603$complementa$m24603$, $m24604$AEPF (nota-0065) e CPV juntos formam os dois eixos da Quadrant Analysis (nota-0067)$m24604$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m24605$nota-0067$m24605$, $m24606$Training and Racing with a Power Meter.pdf$m24606$, $m24607$168$m24607$, $m24608$AEPF and CPV at an individual's threshold power can be used to divide the force-velocity scatterplot from any ride into four quadrants.$m24608$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m24609$nota-0067$m24609$, $m24610$Training and Racing with a Power Meter.pdf$m24610$, $m24611$168$m24611$, $m24612$Quadrant I (upper right): high force and high velocity... Quadrant II (upper left): high force but low velocity... Quadrant III (lower left): low force and low velocity... Quadrant IV (lower right): low force but high velocity.$m24612$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m24613$nota-0067$m24613$, $m24614$nota-0065$m24614$, $m24615$pre-requisito$m24615$, $m24616$usa a AEPF (nota-0065) como eixo de força$m24616$)
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m24617$nota-0067$m24617$, $m24618$nota-0066$m24618$, $m24619$pre-requisito$m24619$, $m24620$usa a CPV (nota-0066) como eixo de velocidade$m24620$)
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m24621$nota-0067$m24621$, $m24622$nota-0074$m24622$, $m24623$causal$m24623$, $m24624$a divisão dos quadrantes é baseada no limiar de recrutamento de fibras rápidas, que ocorre aproximadamente no FTP (nota-0074)$m24624$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m24625$nota-0070$m24625$, $m24626$Training and Racing with a Power Meter.pdf$m24626$, $m24627$183$m24627$, $m24628$The ANT+ protocol... measures the average power from each individual leg and calculates the percentage that each contributes to the total... there is a problem with this simple calculation: When the left leg pushes down on the pedal, the right-leg upstroke creates some resistance on the opposite side, and this negative power is not correctly accounted for.$m24628$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m24629$nota-0070$m24629$, $m24630$Training and Racing with a Power Meter.pdf$m24630$, $m24631$183$m24631$, $m24632$if the left leg releases 150 watts, but the right leg absorbs 20 watts, the net power for the left leg would be 130 watts... if the right leg releases 170 watts, and the left leg absorbs 30 watts, the net power for the right leg would be 140 watts... the correct power balance is 48 percent left and 52 percent right.$m24632$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m24633$nota-0070$m24633$, $m24634$nota-0071$m24634$, $m24635$pre-requisito$m24635$, $m24636$define GPR/GPA/KI, as métricas propostas pelos autores para corrigir o problema descrito nesta nota$m24636$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m24637$nota-0071$m24637$, $m24638$Training and Racing with a Power Meter.pdf$m24638$, $m24639$184$m24639$, $m24640$Gross Power Released (GPR): The gross (i.e., muscular + inertial + gravitational) power released by one leg (left or right), primarily on the downstroke. Gross Power Absorbed (GPA): The gross... power absorbed by one leg... primarily during the upstroke.$m24640$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m24641$nota-0071$m24641$, $m24642$Training and Racing with a Power Meter.pdf$m24642$, $m24643$185$m24643$, $m24644$Kurtotic Index (KI): A measure of the \"peakedness\" of the pattern of force, torque, and power application during the power-producing phase.$m24644$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m24645$nota-0071$m24645$, $m24646$nota-0070$m24646$, $m24647$pre-requisito$m24647$, $m24648$estas métricas foram criadas para corrigir a limitação do power balance ANT+ descrita na nota-0070$m24648$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m24649$nota-0073$m24649$, $m24650$Training and Racing with a Power Meter.pdf$m24650$, $m24651$192$m24651$, $m24652$If one leg is more than 10 percent different in power output than the other. In this case, you need to determine if you have muscular strength discrepancy or a possible movement pattern or bike fit issue.$m24652$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m24653$nota-0073$m24653$, $m24654$Training and Racing with a Power Meter.pdf$m24654$, $m24655$192$m24655$, $m24656$If both legs have a GPA of greater than 35 watts while seated... we suggest you intentionally drive your knee toward the handlebar on the upstroke and lightly point your toe downward throughout the pedal stroke.$m24656$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m24657$nota-0073$m24657$, $m24658$Training and Racing with a Power Meter.pdf$m24658$, $m24659$192$m24659$, $m24660$Riders who deliberately pull up on the pedal stroke actually use more energy and are less efficient... Deliberately modifying the pattern of force application throughout your pedal stroke to emphasize pulling up reduces your metabolic efficiency.$m24660$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m24661$nota-0073$m24661$, $m24662$nota-0071$m24662$, $m24663$pre-requisito$m24663$, $m24664$usa as métricas GPR/GPA definidas na nota-0071$m24664$)
